import sys

def run_brute(k, ops):
    cache = {}
    order = []
    out = []
    for op in ops:
        if op[0] == 'put':
            _, key, value = op
            key = int(key); value = int(value)
            if key in cache:
                order.remove(key)
            cache[key] = value
            order.append(key)
            if len(cache) > k:
                evict = order.pop(0)
                del cache[evict]
        else:
            _, key = op
            key = int(key)
            if key not in cache:
                out.append(-1)
            else:
                order.remove(key)
                order.append(key)
                out.append(cache[key])
    return out

