import sys
from collections import OrderedDict

class LRUCacheBest(OrderedDict):
    def __init__(self, cap):
        super().__init__()
        self.cap = cap
    def get(self, key):
        if key not in self:
            return -1
        self.move_to_end(key)
        return self[key]
    def put(self, key, value):
        if key in self:
            self.move_to_end(key)
        self[key] = value
        if len(self) > self.cap:
            self.popitem(last=False)

